<?php require 'config.php'; fechar_offlines();
$funs=jread('funcionarios',[]); $pres=jread('presencas',[]); $mes=$_GET['mes']??date('Y-m'); $export=$_GET['export']??'';
$linhas=[]; foreach($funs as $f){ $tot=0;$bruto=0;$alm=0;$extra=0;$dias=0;$ajustes=0; foreach($pres as $p){ if(($p['funcionario_id']??'')===$f['id'] && substr($p['data']??'',0,7)===$mes){ $dias++; $tot+=(int)($p['minutos']??0); $bruto+=(int)($p['minutos_brutos']??0); $alm+=(int)($p['almoco_minutos']??0); $extra+=(int)($p['extra_minutos']??0); if(($p['origem']??'')==='manual') $ajustes++; } } $linhas[]=['nome'=>$f['nome'],'cargo'=>$f['cargo']??'Funcionário','dias'=>$dias,'bruto'=>$bruto,'almoco'=>$alm,'liquido'=>$tot,'extra'=>$extra,'ajustes'=>$ajustes]; }
if($export==='csv'){ header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="relatorio_'.$mes.'.csv"'); echo "Funcionário;Cargo;Dias;Bruto;Almoço;Líquido;Extra;Ajustes\n"; foreach($linhas as $l){ echo implode(';',[$l['nome'],$l['cargo'],$l['dias'],hhmm_from_min($l['bruto']),hhmm_from_min($l['almoco']),hhmm_from_min($l['liquido']),hhmm_from_min($l['extra']),$l['ajustes']])."\n"; } exit; }
header_page('Relatório mensal');
?>
<div class="card"><h2>Relatório mensal</h2><form method="get" class="inline"><label>Mês</label><input type="month" name="mes" value="<?=h($mes)?>"><button>Filtrar</button><a class="btn" href="relatorios.php?mes=<?=h($mes)?>&export=csv">Baixar Excel/CSV</a></form></div><br>
<div class="card"><table><tr><th>Funcionário</th><th>Cargo</th><th>Dias</th><th>Horas brutas</th><th>Almoço</th><th>Horas trabalhadas</th><th>Hora extra</th><th>Correções</th></tr><?php foreach($linhas as $l): ?><tr><td><?=h($l['nome'])?></td><td><?=h($l['cargo'])?></td><td><?=$l['dias']?></td><td><?=hhmm_from_min($l['bruto'])?></td><td><?=hhmm_from_min($l['almoco'])?></td><td><b><?=hhmm_from_min($l['liquido'])?></b></td><td><?=hhmm_from_min($l['extra'])?></td><td><?=$l['ajustes']?></td></tr><?php endforeach; ?></table></div><br>
<div class="card"><h2>Detalhado por dia</h2><table><tr><th>Data</th><th>Funcionário</th><th>Entrada</th><th>Saída</th><th>Almoço</th><th>Total</th><th>Extra</th><th>Status</th></tr><?php foreach($pres as $p): if(substr($p['data']??'',0,7)!==$mes) continue; $nome=''; foreach($funs as $f){ if($f['id']===($p['funcionario_id']??'')) $nome=$f['nome']; } ?><tr><td><?=date('d/m/Y',strtotime($p['data']))?></td><td><?=h($nome)?></td><td><?=!empty($p['entrada'])?date('H:i',strtotime($p['entrada'])):'--'?></td><td><?=!empty($p['saida'])?date('H:i',strtotime($p['saida'])):'--'?></td><td><?=hhmm_from_min($p['almoco_minutos']??0)?></td><td><b><?=hhmm_from_min($p['minutos']??0)?></b></td><td><?=hhmm_from_min($p['extra_minutos']??0)?></td><td><?=h($p['status']??'')?></td></tr><?php endforeach; ?></table></div>
<?php footer_page(); ?>
